    $order=$this->resolveOrderInstance($orderOrId);
    if(!$order->canCancel($force))return false;
    Event::dispatch('sales.order.cancel.before', $order);
    foreach($order->items as $item){
        if(!$item->canCancel($force))continue;
        $this->orderItemRepository->returnQtyToProductInventory($item);
        if($item->qty_ordered){$item->qty_canceled+=$item->qty_to_cancel;$item->save();}
    }
    $this->updateOrderStatus($order);
    Event::dispatch('sales.order.cancel.after', $order);
    return true;
}

